export function mangaDirectoryColor(role: string, scheme: string): string {
  const theme = scheme === 'night' || scheme === 'theme-dark' ? 'night' : 'day';
  switch (role) {
    case 'surface': return readerAppColor('TOK_CARD_BG', theme);
    case 'ink': return readerAppColor('TOK_INK', theme);
    case 'faint': return readerAppColor('app.text.subtle', theme);
    case 'accent': return readerAppColor('TOK_PRIMARY_TEXT', theme);
    case 'line': return readerAppColor('TOK_LINE', theme);
    default: return readerAppColor('TOK_INK', theme);
  }
}

